window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-10157b7a9cdbd933"]={"versions": [{"id": "FIG-10157b7a9cdbd933", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des formalen M2-Metamodells der AUTOSAR Adaptive Platform).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Tracing- und Verfeinerungsmechanismus zwischen abstraktem Anwendungsentwurf (<code>ApplicationDesign</code>) und konkreter Zielplattform-Konfiguration (<code>Deployment</code> / Machine Manifest) für kryptografische Schlüsselspeicher gemäß Anforderung <strong><code>TPS_MANI_01472</code></strong>.</li>\n<li><strong>Funktionale Einordnung:</strong> Entkopplung der Entwicklerrollen im Security-Subsystem (<code>ara::crypto</code>). Der Software-Architekt definiert funktionale Krypto-Anforderungen ohne Hardware-Bindung; der System-Integrator mappt diese auf physische oder virtuelle Speicherbereiche (z. B. HSM, Secure Storage, TrustZone).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>CryptoKeySlotDesign</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Repräsentiert die abstrakte Design-Anforderung eines Key-Slots im <code>ApplicationDesign</code>.</li>\n<li><em>Attribute:</em></li>\n<li><code>cryptoAlgorithmId: String [0..1]</code> – Beabsichtigter Krypto-Algorithmus (z. B. AES-128, ECDSA-SECP256R1) als formloser Identifikator.</li>\n<li><code>cryptoObjectType: String [0..1]</code> – Generische Typbezeichnung des zu speichernden Objekts (z. B. symmetrischer Schlüssel, privater Schlüssel, Zertifikat).</li>\n<li><code>shared: Boolean [0..1]</code> – Definiert, ob der Slot designseitig für mehrere Prozesse/Applikationen freigegeben ist.</li>\n<li><code>slotCapacity: PositiveInteger [0..1]</code> – Vom Entwurf geforderte Mindest-Nutzlastgröße in Bytes.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>CryptoKeySlot</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Repräsentiert die konkrete Allokation des Schlüsselspeichers im Zielsystem (Execution-/Machine-Manifest).</li>\n<li><em>Attribute:</em></li>\n<li><code>allocateShadowCopy: Boolean [0..1]</code> – Steuert die hardware-/treiberseitige Bereitstellung einer Schattenbank (Shadow Copy) für atomare Schlüssel-Updates und Ausfallsicherheit (Power-Loss Protection).</li>\n<li><code>cryptoAlgId: String [0..1]</code> – Tatsächlich konfigurierte Algorithmenkennung für den angebundenen Crypto Provider / Treiber.</li>\n<li><code>cryptoObjectType: CryptoObjectTypeEnum [0..1]</code> – Streng typisierte Enumeration des Objekttyps (Einschränkung des freien Design-Strings auf plattformdefinierte Standardwerte).</li>\n<li><code>slotCapacity: PositiveInteger [0..1]</code> – Physisch im HSM/Flash allokierte Speicherkapazität in Bytes.</li>\n<li><code>slotType: CryptoKeySlotTypeEnum [0..1]</code> – Persistenz- und Lebensdauer-Klassifikation (z. B. persistent, transient, session-gebunden).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungen & Multiplizitäten:</strong></li>\n<li><strong>Assoziation:</strong> Gerichtete Referenz von <code>CryptoKeySlot</code> zu <code>CryptoKeySlotDesign</code> mit Rollenname <code>+cryptoKeySlotDesign</code> und Kardinalität <code>0..1</code>.</li>\n<li>Ein Deployment-Slot verweist optional auf maximal ein Design-Element. Kardinalität <code>0</code> erlaubt maschinenspezifische Slots (z. B. Platform-Root-Keys, OS-interne Slots), die ohne Entsprechung im Application Design existieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Entwurfs- und Manifest-Validierung (Build-Time):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Application Modeling:</em> Architekt deklariert <code>CryptoKeySlotDesign</code>.</li>\n<li><em>Trace-Bindung:</em> Integrator instanziiert <code>CryptoKeySlot</code> und setzt die Referenz <code>cryptoKeySlotDesign</code>.</li>\n<li><em>Konsistenzprüfung (TPS_MANI_01472):</em> Validierungs-Tools prüfen statisch:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CryptoKeySlot.slotCapacity &gt;= CryptoKeySlotDesign.slotCapacity</code></li>\n<li>Verträglichkeit von <code>cryptoAlgId</code> mit <code>cryptoAlgorithmId</code></li>\n<li>Gültigkeit des Mappings von <code>cryptoObjectType</code> (String) auf <code>CryptoObjectTypeEnum</code>.</li>\n<li><strong>Stack-Initialisierung (Runtime):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der Crypto-Provider-Daemon parst das Manifest beim Booten.</li>\n<li>Allokation und Registrierung des Slots im physikalischen Backend (NVM/HSM) basierend auf <code>slotType</code> und <code>slotCapacity</code>.</li>\n<li>Einrichtung von Schreib-Spiegeln bei gesetztem <code>allocateShadowCopy = true</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Treiber- und Plattform-Entwickler (HSM / Crypto Provider):</strong></li>\n<li><code>allocateShadowCopy</code>: Erfordert im Treiber-Backend eine A/B-Pufferung oder doppelte Flash-Pages. Bei schreibenden API-Aufrufen (<code>ara::crypto::keys::KeySlot::SaveCopy()</code>) muss das Update atomar erfolgen, bevor der aktive Zeiger umgeschaltet wird.</li>\n<li><code>slotType</code>: Bestimmt das Zielmedium; transiente Slots müssen im flüchtigen RAM liegen und beim Prozessabbruch sicher genullt werden, persistente Slots verlangen NVM/HSM-Non-Volatile Memory.</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li>Applikationen binden sich gegen das Interface von <code>ara::crypto</code> über logische Referenzen (<code>InstanceSpecifier</code> auf Design-Ebene); sie haben keine Kenntnis über physikalische Slot-Indizes oder <code>allocateShadowCopy</code>.</li>\n<li><strong>Integrations- & Tooling-Restriktionen:</strong></li>\n<li><code>cryptoObjectType</code> vollzieht den Übergang von weakly typed (<code>String</code>) im Design zu strongly typed (<code>CryptoObjectTypeEnum</code>) im Deployment. Konfigurations-Generatoren müssen fehlerhafte String-Eingaben zur Compile-Zeit abweisen.</li>\n</ul>"}, {"id": "FIG-22bff8efd4abfc21", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des formalen M2-Metamodells der AUTOSAR Adaptive Platform).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Tracing- und Verfeinerungsmechanismus zwischen abstraktem Anwendungsentwurf (<code>ApplicationDesign</code>) und konkreter Zielplattform-Konfiguration (<code>Deployment</code> / Machine Manifest) für kryptografische Schlüsselspeicher gemäß Anforderung <strong><code>TPS_MANI_01472</code></strong>.</li>\n<li><strong>Funktionale Einordnung:</strong> Entkopplung der Entwicklerrollen im Security-Subsystem (<code>ara::crypto</code>). Der Software-Architekt definiert funktionale Krypto-Anforderungen ohne Hardware-Bindung; der System-Integrator mappt diese auf physische oder virtuelle Speicherbereiche (z. B. HSM, Secure Storage, TrustZone).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>CryptoKeySlotDesign</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Repräsentiert die abstrakte Design-Anforderung eines Key-Slots im <code>ApplicationDesign</code>.</li>\n<li><em>Attribute:</em></li>\n<li><code>shared: Boolean [0..1]</code> – Definiert, ob der Slot designseitig für mehrere Prozesse/Applikationen freigegeben ist.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>CryptoKeySlot</code></strong> (spezialisiert <code>Identifiable</code>):</li>\n<li>Repräsentiert die konkrete Allokation des Schlüsselspeichers im Zielsystem (Execution-/Machine-Manifest).</li>\n<li><em>Attribute:</em></li>\n<li><code>allocateShadowCopy: Boolean [0..1]</code> – Steuert die hardware-/treiberseitige Bereitstellung einer Schattenbank (Shadow Copy) für atomare Schlüssel-Updates und Ausfallsicherheit (Power-Loss Protection).</li>\n<li><code>cryptoAlgId: String [0..1]</code> – Tatsächlich konfigurierte Algorithmenkennung für den angebundenen Crypto Provider / Treiber.</li>\n<li><code>cryptoObjectType: CryptoObjectTypeEnum [0..1]</code> – Streng typisierte Enumeration des Objekttyps.</li>\n<li><code>slotCapacity: PositiveInteger [0..1]</code> – Physisch im HSM/Flash allokierte Speicherkapazität in Bytes.</li>\n<li><code>slotType: CryptoKeySlotTypeEnum [0..1]</code> – Persistenz- und Lebensdauer-Klassifikation (z. B. persistent, transient, session-gebunden).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungen & Multiplizitäten:</strong></li>\n<li><strong>Assoziation:</strong> Gerichtete Referenz von <code>CryptoKeySlot</code> zu <code>CryptoKeySlotDesign</code> mit Rollenname <code>+cryptoKeySlotDesign</code> und Kardinalität <code>0..1</code>.</li>\n<li>Ein Deployment-Slot verweist optional auf maximal ein Design-Element. Kardinalität <code>0</code> erlaubt maschinenspezifische Slots (z. B. Platform-Root-Keys, OS-interne Slots), die ohne Entsprechung im Application Design existieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Entwurfs- und Manifest-Validierung (Build-Time):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Application Modeling:</em> Architekt deklariert <code>CryptoKeySlotDesign</code> (inkl. <code>shared</code>-Freigabekonfiguration).</li>\n<li><em>Trace-Bindung:</em> Integrator instanziiert <code>CryptoKeySlot</code> und setzt die Referenz <code>cryptoKeySlotDesign</code>.</li>\n<li><em>Konsistenzprüfung (TPS_MANI_01472):</em> Validierungs-Tools prüfen statisch die Referenzkonsistenz; die detaillierten Krypto-Eigenschaften (<code>cryptoAlgId</code>, <code>cryptoObjectType</code>, <code>slotCapacity</code>) werden im Deployment direkt am <code>CryptoKeySlot</code> vorgegeben.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Stack-Initialisierung (Runtime):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der Crypto-Provider-Daemon parst das Manifest beim Booten.</li>\n<li>Allokation und Registrierung des Slots im physikalischen Backend (NVM/HSM) basierend auf <code>slotType</code> und <code>slotCapacity</code>.</li>\n<li>Einrichtung von Schreib-Spiegeln bei gesetztem <code>allocateShadowCopy = true</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Treiber- und Plattform-Entwickler (HSM / Crypto Provider):</strong></li>\n<li><code>allocateShadowCopy</code>: Erfordert im Treiber-Backend eine A/B-Pufferung oder doppelte Flash-Pages. Bei schreibenden API-Aufrufen (<code>ara::crypto::keys::KeySlot::SaveCopy()</code>) muss das Update atomar erfolgen, bevor der aktive Zeiger umgeschaltet wird.</li>\n<li><code>slotType</code>: Bestimmt das Zielmedium; transiente Slots müssen im flüchtigen RAM liegen und beim Prozessabbruch sicher genullt werden, persistente Slots verlangen NVM/HSM-Non-Volatile Memory.</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li>Applikationen binden sich gegen das Interface von <code>ara::crypto</code> über logische Referenzen (<code>InstanceSpecifier</code> auf Design-Ebene); sie haben keine Kenntnis über physikalische Slot-Indizes oder <code>allocateShadowCopy</code>.</li>\n<li><strong>Integrations- & Tooling-Restriktionen:</strong></li>\n<li>Da <code>cryptoAlgorithmId</code>, <code>cryptoObjectType</code> und <code>slotCapacity</code> aus <code>CryptoKeySlotDesign</code> entfernt wurden, erfolgt die Festlegung von Algorithmus, Objekttyp und Puffergröße ausschließlich im Deployment am <code>CryptoKeySlot</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-10157b7a9cdbd933", "to": "FIG-22bff8efd4abfc21", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>CryptoKeySlotDesign</code>: Attribute <code>cryptoAlgorithmId: String [0..1]</code>, <code>cryptoObjectType: String [0..1]</code> und <code>slotCapacity: PositiveInteger [0..1]</code> entfernt; es verbleibt <code>shared: Boolean [0..1]</code>.</li>\n</ul>"}]};
